//! The test projects, baked into the binary: the page runs in a browser
//! with no disk, so it opens these (fit-check §7).
//!
//! - the PLAYFUL choker (`catalog/projects/playful-choker`): 73 lamps on
//!   12 paths, one output whose one port takes the rest;
//! - the zook dome (`catalog/projects/zook-dome`): a 5-way repeat of a
//!   300-lamp zigzag path with a jumper, 5 ports;
//! - the radiance dome (`lab/mapping/projects/radiance-dome`, generated by
//!   `lab-mapping-radiance-gen`, placeholder counts): 55 panel shapes × 5,
//!   22,000 lamps, 10 outputs × 32 ports, patched by hand.
//!
//! Only the JSON the lab reads is baked in; shaders are not.

use crate::source::MemFiles;

/// One test project: what the picker calls it, and its files.
pub struct Embedded {
    pub key: &'static str,
    pub title: &'static str,
    files: &'static [(&'static str, &'static str)],
}

impl Embedded {
    pub fn files(&self) -> MemFiles {
        MemFiles::new(self.files.iter().copied())
    }
}

macro_rules! files {
    ($dir:literal: $($name:literal),* $(,)?) => {
        &[$(($name, include_str!(concat!($dir, "/", $name)))),*]
    };
}

pub const CHOKER: Embedded = Embedded {
    key: "playful-choker",
    title: "PLAYFUL choker",
    files: files!("../../../../catalog/projects/playful-choker":
        "project.json", "module.json", "clock.json", "fixture.json", "output.json",
        "power.json", "shader.json", "playful.map2d.json"),
};

pub const ZOOK_DOME: Embedded = Embedded {
    key: "zook-dome",
    title: "Zook dome",
    files: files!("../../../../catalog/projects/zook-dome":
        "project.json", "module.json", "clock.json", "fixture.json", "fixture.map2d.json",
        "output.json", "shader.json"),
};

pub const RADIANCE_DOME: Embedded = Embedded {
    key: "radiance-dome",
    title: "Radiance dome",
    files: files!("../../projects/radiance-dome":
        "project.json", "module.json", "clock.json", "shader.json", "dome.json",
        "dome.map2d.json", "dome.patch.json", "out_1.json", "out_2.json", "out_3.json",
        "out_4.json", "out_5.json", "out_6.json", "out_7.json", "out_8.json", "out_9.json",
        "out_10.json"),
};

/// Every baked-in project, in the picker's order.
pub const ALL: [&Embedded; 3] = [&CHOKER, &ZOOK_DOME, &RADIANCE_DOME];
